param([string]$OutputDir = "$env:TEMP\QingheTenToolsBuild")
$ErrorActionPreference = 'Stop'
$root = $PSScriptRoot; $sdk = if ($env:ANDROID_HOME) { $env:ANDROID_HOME } elseif ($env:ANDROID_SDK_ROOT) { $env:ANDROID_SDK_ROOT } else { 'D:\AndroidDev\Android\Sdk' }; $bt = Join-Path $sdk 'build-tools\36.0.0'; $androidJar = Join-Path $sdk 'platforms\android-36\android.jar'; $javaHome = if ($env:JAVA_HOME) { $env:JAVA_HOME } else { 'D:\AndroidDev\Android Studio\jbr' }; $aapt2 = Join-Path $bt 'aapt2.exe'; $javac = Join-Path $javaHome 'bin\javac.exe'; $jar = Join-Path $javaHome 'bin\jar.exe'; $d8 = Join-Path $bt 'd8.bat'; $zipalign = Join-Path $bt 'zipalign.exe'; $apksigner = Join-Path $bt 'apksigner.bat'; $outRoot = [System.IO.Path]::GetFullPath($OutputDir); [System.IO.Directory]::CreateDirectory($outRoot)|Out-Null
$template = Get-Content (Join-Path $root 'tools-10\ToolActivity.java.template') -Raw; $apps = Get-Content (Join-Path $root 'tools-10\apps.json') -Raw | ConvertFrom-Json
foreach ($app in $apps) {
  $work = Join-Path $outRoot $app.id; $res = Join-Path $work 'res'; $src = Join-Path $work ('src\' + ($app.package -replace '\.','\')); $gen = Join-Path $work 'generated'; $classes = Join-Path $work 'classes'; $dex = Join-Path $work 'dex'; foreach($d in @($res,$src,$gen,$classes,$dex)){[System.IO.Directory]::CreateDirectory($d)|Out-Null}; [System.IO.Directory]::CreateDirectory((Join-Path $res 'values'))|Out-Null; [System.IO.Directory]::CreateDirectory((Join-Path $res 'drawable'))|Out-Null
  $manifest = @"
<?xml version="1.0" encoding="utf-8"?><manifest xmlns:android="http://schemas.android.com/apk/res/android" package="$($app.package)"><application android:allowBackup="true" android:label="$($app.label)" android:theme="@style/Theme.Tool"><activity android:name=".MainActivity" android:exported="true" android:screenOrientation="portrait"><intent-filter><action android:name="android.intent.action.MAIN"/><category android:name="android.intent.category.LAUNCHER"/></intent-filter></activity></application></manifest>
"@; Set-Content (Join-Path $work 'AndroidManifest.xml') $manifest -Encoding utf8
  $strings = @"
<resources><string name="app_name">$($app.label)</string></resources>
"@; Set-Content (Join-Path $res 'values\strings.xml') $strings -Encoding utf8; Set-Content (Join-Path $res 'values\styles.xml') '<resources><style name="Theme.Tool" parent="android:style/Theme.Material.Light.NoActionBar"><item name="android:fontFamily">sans</item><item name="android:colorAccent">#6D5DFC</item><item name="android:statusBarColor">#20233A</item><item name="android:navigationBarColor">#20233A</item></style></resources>' -Encoding utf8
  $java = $template.Replace('__PACKAGE__',$app.package).Replace('__TOOL_KIND__',$app.kind).Replace('__APP_LABEL__',$app.label).Replace('__DESCRIPTION__',$app.description); Set-Content (Join-Path $src 'MainActivity.java') $java -Encoding utf8
  $resZip = Join-Path $work 'resources.zip'; $unsigned = Join-Path $work 'unsigned.apk'; $aligned = Join-Path $work 'aligned.apk'; $apk = Join-Path $outRoot ($app.id + '-debug.apk')
  & $aapt2 compile --dir $res -o $resZip; & $aapt2 link -o $unsigned -I $androidJar --manifest (Join-Path $work 'AndroidManifest.xml') --java $gen --auto-add-overlay --min-sdk-version 23 --target-sdk-version 36 --version-code 1 --version-name 1.0 $resZip
  $rJava = Join-Path $gen (($app.package -replace '\.','\') + '\R.java'); & $javac --release 17 -encoding UTF-8 -classpath $androidJar -d $classes $rJava (Join-Path $src 'MainActivity.java'); $classFiles = @(Get-ChildItem $classes -Recurse -Filter '*.class' | ForEach-Object FullName); & $d8 --lib $androidJar --output $dex $classFiles; Push-Location $dex; try { & $jar uf $unsigned 'classes.dex' } finally { Pop-Location }; & $zipalign -f -p 4 $unsigned $aligned; & $apksigner sign --ks (Join-Path $env:USERPROFILE '.android\debug.keystore') --ks-key-alias androiddebugkey --ks-pass pass:android --key-pass pass:android --out $apk $aligned
  Write-Host "Generated $apk"
}

